#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;

char mazeA[MAXN][MAXN], mazeB[MAXN][MAXN];
int distMap[MAXN][MAXN];
int n, t;

int dirX[] = {1, 0, -1, 0};
int dirY[] = {0, 1, 0, -1};

void perform_bfs(int startX, int startY) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            distMap[i][j] = INF;
    distMap[startX][startY] = 0;
    queue<pair<int, int>> q;
    q.push({startX, startY});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if ('0' <= mazeA[nx][ny] && mazeA[nx][ny] <= '9' && distMap[nx][ny] == INF) {
                distMap[nx][ny] = distMap[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

vector<int> graph[MAXV];
int cap[MAXV][MAXV];

void connect_edge(int u, int v, int c) {
    graph[u].push_back(v);
    graph[v].push_back(u);
    cap[u][v] = c;
    cap[v][u] = 0;
}

int time_grid[MAXN][MAXN];
bool visited_nodes[MAXV];
int level[MAXV];

bool build_bfs_levels(int s, int t) {
    memset(level, -1, sizeof(level));
    level[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty() && level[t] == -1) {
        int v = q.front(); q.pop();
        for (auto &nxt : graph[v]) {
            if (!cap[v][nxt] || level[nxt] != -1) continue;
            level[nxt] = level[v] + 1;
            q.push(nxt);
        }
    }
    return level[t] != -1;
}

void explore_bfs_variant(int px, int py) {
    memset(time_grid, INF, sizeof(time_grid));
    time_grid[px][py] = 0;
    if ('1' <= mazeB[px][py] && mazeB[px][py] <= '9')
        connect_edge(n * px + py, n * n + n * px + py, INF);
    queue<pair<int, int>> q;
    q.push({px, py});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if (time_grid[nx][ny] != INF) continue;
            if (!('0' <= mazeA[nx][ny] && mazeA[nx][ny] <= '9')) continue;
            if (time_grid[x][y] + 1 <= min(distMap[nx][ny] - 1, t)) {
                time_grid[nx][ny] = time_grid[x][y] + 1;
                q.push({nx, ny});
            }
            if (time_grid[x][y] + 1 <= min(distMap[nx][ny], t) && '1' <= mazeB[nx][ny] && mazeB[nx][ny] <= '9')
                connect_edge(n * px + py, n * n + n * nx + ny, INF);
        }
    }
}

int dfs_flow_variant(int v, int t, int f) {
    if (v == t) return f;
    visited_nodes[v] = true;
    for (auto &nxt : graph[v]) {
        if (!cap[v][nxt] || visited_nodes[nxt] || level[nxt] != level[v] + 1) continue;
        int pushed = dfs_flow_variant(nxt, t, min(f, cap[v][nxt]));
        if (pushed) {
            cap[v][nxt] -= pushed;
            cap[nxt][v] += pushed;
            return pushed;
        }
    }
    return 0;
}

int compute_max_flow_variant(int s, int t) {
    int total_flow = 0, flow;
    while (build_bfs_levels(s, t)) {
        memset(visited_nodes, 0, sizeof(visited_nodes));
        while ((flow = dfs_flow_variant(s, t, INF)) > 0) {
            total_flow += flow;
            memset(visited_nodes, 0, sizeof(visited_nodes));
        }
    }
    return total_flow;
}

int main() {
    cin >> n >> t;
    int startX, startY;
    int s_node = MAXV - 2, t_node = MAXV - 1;
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> mazeA[a][b];
            if (mazeA[a][b] == 'Z') {
                startX = a; startY = b;
            } else if ('1' <= mazeA[a][b] && mazeA[a][b] <= '9') {
                connect_edge(s_node, a * n + b, mazeA[a][b] - '0');
            }
        }
    }
    perform_bfs(startX, startY);
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> mazeB[a][b];
            if ('1' <= mazeB[a][b] && mazeB[a][b] <= '9') {
                connect_edge(n * n + a * n + b, t_node, mazeB[a][b] - '0');
            }
