import java.util.*;
import java.io.*;

public class MazeFlow {
    static final int INF = 0x3f3f3f3f;
    static final int MAXN = 20;
    static final int MAXV = 2 * MAXN * MAXN;

    static char[][] mazeA = new char[MAXN][MAXN];
    static char[][] mazeB = new char[MAXN][MAXN];
    static int[][] distMap = new int[MAXN][MAXN];
    static int n, t;

    static int[] dirX = {1, 0, -1, 0};
    static int[] dirY = {0, 1, 0, -1};

    static List<Integer>[] graph = new ArrayList[MAXV];
    static int[][] cap = new int[MAXV][MAXV];

    static int[] timeGrid = new int[MAXN][MAXN];
    static boolean[] visitedNodes = new boolean[MAXV];
    static int[] level = new int[MAXV];

    static int startX, startY;

    static {
        for (int i = 0; i < MAXV; i++) {
            graph[i] = new ArrayList<>();
        }
    }

    static void performBFS(int startX, int startY) {
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                distMap[i][j] = INF;
        distMap[startX][startY] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{startX, startY});
        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int x = pos[0], y = pos[1];
            for (int d = 0; d < 4; ++d) {
                int nx = x + dirX[d], ny = y + dirY[d];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if ('0' <= mazeA[nx][ny] && mazeA[nx][ny] <= '9' && distMap[nx][ny] == INF) {
                    distMap[nx][ny] = distMap[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static void connectEdge(int u, int v, int c) {
        graph[u].add(v);
        graph[v].add(u);
        cap[u][v] = c;
        cap[v][u] = 0;
    }

    static boolean buildBFSLevels(int s, int t) {
        Arrays.fill(level, -1);
        level[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty() && level[t] == -1) {
            int v = q.poll();
            for (int nxt : graph[v]) {
                if (cap[v][nxt] == 0 || level[nxt] != -1) continue;
                level[nxt] = level[v] + 1;
                q.offer(nxt);
            }
        }
        return level[t] != -1;
    }

    static void exploreBFSVariant(int px, int py) {
        for (int i = 0; i < n; ++i)
            Arrays.fill(timeGrid[i], INF);
        timeGrid[px][py] = 0;
        if ('1' <= mazeB[px][py] && mazeB[px][py] <= '9')
            connectEdge(n * px + py, n * n + n * px + py, INF);
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{px, py});
        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int x = pos[0], y = pos[1];
            for (int d = 0; d < 4; ++d) {
                int nx = x + dirX[d], ny = y + dirY[d];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if (timeGrid[nx][ny] != INF) continue;
                if (!('0' <= mazeA[nx][ny] && mazeA[nx][ny] <= '9')) continue;
                if (timeGrid[x][y] + 1 <= Math.min(distMap[nx][ny] - 1, t)) {
                    timeGrid[nx][ny] = timeGrid[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
                if (timeGrid[x][y] + 1 <= Math.min(distMap[nx][ny], t) && ('1' <= mazeB[nx][ny] && mazeB[nx][ny] <= '9'))
                    connectEdge(n * px + py, n * n + n * nx + ny, INF);
            }
        }
    }

    static int dfsFlowVariant(int v, int t, int f) {
        if (v == t) return f;
        visitedNodes[v] = true;
        for (int nxt : graph[v]) {
            if (cap[v][nxt] == 0 || visitedNodes[nxt] || level[nxt] != level[v] + 1) continue;
            int pushed = dfsFlowVariant(nxt, t, Math.min(f, cap[v][nxt]));
            if (pushed > 0) {
                cap[v][nxt] -= pushed;
                cap[nxt][v] += pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int computeMaxFlowVariant(int s, int t) {
        int totalFlow = 0, flow;
        while (buildBFSLevels(s, t)) {
            Arrays.fill(visitedNodes, false);
            while ((flow = dfsFlowVariant(s, t, INF)) > 0) {
                totalFlow += flow;
                Arrays.fill(visitedNodes, false);
            }
        }
        return totalFlow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        int s_node = MAXV - 2;
        int t_node = MAXV - 1;

        for (int a = 0; a < n; ++a) {
            String line = br.readLine();
            for (int b = 0; b < n; ++b) {
                mazeA[a][b] = line.charAt(b);
                if (mazeA[a][b] == 'Z') {
                    startX = a;
                    startY = b;
                } else if ('1' <= mazeA[a][b] && mazeA[a][b] <= '9') {
                    connectEdge(s_node, a * n + b, mazeA[a][b] - '0');
                }
            }
        }
        performBFS(startX, startY);
        for (int a = 0; a < n; ++a) {
            String line = br.readLine();
            for (int b = 0; b < n; ++b) {
                mazeB[a][b] = line.charAt(b);
                if ('1' <= mazeB[a][b] && mazeB[a][b] <= '9') {
                    connectEdge(n * n + a * n + b, t_node, mazeB[a][b] - '0');
                }
            }
        }
        for (int a = 0; a < n; ++a) {
            for (int b = 0; b < n; ++b) {
                if ('1' <= mazeA[a][b] && mazeA[a][b] <= '9') {
                    exploreBFSVariant(a, b);
                }
            }
        }
        System.out.println(computeMaxFlowVariant(s_node, t_node));
    }
}
